import { circuitBreaker, handleWhenResult, ConsecutiveBreaker, wrap, retry, handleAll } from 'cockatiel';

const payments = circuitBreaker(handleWhenResult((res: Response) => res.status >= 500), {
  halfOpenAfter: 15_000,                 // cooldown before the trial call
  breaker: new ConsecutiveBreaker(5),    // trip after 5 consecutive failures
});
const pipeline = wrap(retry(handleAll, { maxAttempts: 2 }), payments);

const receipt = await pipeline.execute<Receipt>(({ signal }) => api.authorize(order, signal));
